export function parseConsumeRandomnessInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedConsumeRandomnessInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 12,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === DEADROLL_SESSION_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      vrfProgramIdentity: getNextAccount(),
      session: getNextAccount(),
      monsters: getNextAccount(),
      participation: getNextAccount(),
      character: getNextAccount(),
      skillSet: getNextAccount(),
      bag: getNextAccount(),
      sessionAuthority: getNextAccount(),
      config: getNextAccount(),
      characterProgram: getNextAccount(),
      targetParticipation: getNextOptionalAccount(),
      layout: getNextAccount(),
    },
    data: getConsumeRandomnessInstructionDataDecoder().decode(instruction.data),
  };
}
